    end
    on_intel do
      url "https://github.com/goadesign/chorus/releases/download/v0.12.0/chorus_0.12.0_darwin_amd64.tar.gz"
      sha256 "4ccb9bd69b44e1559f8d61699f51d9b19b5a2333850e480e8abad554d1733a1f"
    end
  end

  on_linux do
    on_arm do
